package com.bank.dsa;

import java.util.logging.*;

// Runnable demo: decide leap year to pick the interest day count (365 vs 366).
public class LeapYearDemo {
    private static final Logger log = Logger.getLogger(LeapYearDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LeapYearService service = new LeapYearService();

        int year = 2000;
        boolean leap = service.isLeapYear(year);
        int days = leap ? 366 : 365;
        log.info(() -> year + " is " + (leap ? "a Leap Year" : "Not a Leap Year")
                + " -> interest day count = " + days);
    }
}

// ─── Would be in LeapYearService.java in a real project ───
class LeapYearService {
    // Explicit Gregorian rule (matches the flowchart). In prod, prefer Year.of(year).isLeap().
    boolean isLeapYear(int year) {
        if (year < 1) {
            throw new IllegalArgumentException("Year must be positive: " + year);
        }
        boolean explicit = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
        boolean library  = java.time.Year.of(year).isLeap();  // authoritative check
        assert explicit == library : "leap-year logic mismatch for " + year;
        return library;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
